import requests
from ipaddress import ip_network

def scan_ip(ip):
    try:
        response = requests.get(f'http://{ip}', timeout=2, headers={'User-Agent': 'NetworkScanner'})
        if response.status_code == 200:
            server_header = response.headers.get('Server', 'Unknown')
            print(f'{ip}: {server_header}')
    except requests.RequestException as e:
        pass

def main():
    network = ip_network('172.17.0.0/16')
    for ip in network.hosts():
        scan_ip(str(ip))

if __name__ == '__main__':
    main()
