  "content": "import socket
import http.client

# Define the network range
network_range = '172.17.0.0/16'

# Function to get the HTTP Server header
def get_http_server_header(ip):
    try:
        conn = http.client.HTTPConnection(ip, timeout=5)
        conn.request('GET', '/')
        response = conn.getresponse()
        server_header = response.getheader('Server')
        conn.close()
        return server_header
    except Exception as e:
        return None

# Function to scan the network
def scan_network(network_range):
    base_ip = network_range.split('/')[0]
    for i in range(1, 256):
        for j in range(1, 256):
            ip = f'{base_ip[:-3]}{i}.{j}'
            try:
                # Create a socket object
                sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
                sock.settimeout(5)
                result = sock.connect_ex((ip, 80))
                if result == 0:
                    server_header = get_http_server_header(ip)
                    if server_header:
                        print(f'IP: {ip}, HTTP Server: {server_header}')
                sock.close()
            except Exception as e:
                pass

# Run the scan
if __name__ == '__main__':
    scan_network(network_range)
"
}

