    """

    def __init__(self, pdf_path: str):
        """
        Initialize the DocViewer with a PDF file path.

        Args:
            pdf_path (str): Path to the PDF file to open
        """
        self.pdf_path = pdf_path
        self.pdf_reader = None
        self._load_pdf()

    def _load_pdf(self) -> None:
        """
        Load the PDF file for processing.
        """
        if not os.path.exists(self.pdf_path):
            raise FileNotFoundError(f"PDF file not found: {self.pdf_path}")

        try:
            self.pdf_reader = PyPDF2.PdfReader(self.pdf_path)
        except Exception as e:
            raise ValueError(f"Failed to load PDF: {str(e)}")

    def get_document_info(self) -> Dict:
        """
        Get basic document information.

        Returns:
            Dict: Document metadata including title, author, etc.
        """
        if not self.pdf_reader:
            return {}

        info = {}
        if hasattr(self.pdf_reader, 'metadata'):
            info = dict(self.pdf_reader.metadata or {})

        # Add page count
        info['page_count'] = len(self.pdf_reader.pages) if self.pdf_reader else 0

        return info

    def extract_technical_specs(self) -> List[Dict]:
        """
        Extract embedded technical specifications from the PDF.

        Returns:
            List[Dict]: List of technical specifications found in the document
        """
        specs = []

        # First, check document metadata for technical specs
        if hasattr(self.pdf_reader, 'metadata'):
            metadata = dict(self.pdf_reader.metadata or {})
            for key, value in metadata.items():
                if 'technical' in key.lower() or 'spec' in key.lower():
                    specs.append({
                        'type': 'metadata',
                        'key': key,
                        'value': value,
                        'source': 'document_metadata'
                    })

        # Check for technical specs in document content
        for i, page in enumerate(self.pdf_reader.pages):
            text = page.extract_text()

            # Look for common technical spec patterns
            if 'technical specification' in text.lower() or 'specification' in text.lower():
                # Simple extraction - in a real implementation, you'd want more sophisticated parsing
                lines = text.split('\n')
                for line in lines:
                    if any(term in line.lower() for term in ['version', 'model', 'interface', 'protocol', 'requirements', 'specs']):
                        specs.append({
                            'type': 'content',
                            'page': i + 1,
                            'text': line.strip(),
                            'source': 'page_content'
                        })

        return specs

    def display_document(self) -> None:
        """
        Display basic information about the document.
        """
        info = self.get_document_info()
        print(f"Document: {os.path.basename(self.pdf_path)}")
        print(f"Pages: {info.get('page_count', 0)}")

        if 'title' in info:
            print(f"Title: {info['title']}")
        if 'author' in info:
            print(f"Author: {info['author']}")

        print("\nTechnical Specifications Found:")
        specs = self.extract_technical_specs()
        if not specs:
            print("No technical specifications found.")
        else:
            for i, spec in enumerate(specs, 1):
                print(f"{i}. {spec['type'].capitalize()} - {spec['source']}: {spec['text'] if 'text' in spec else spec['value']}")
