"""
Secure codebase verification script for pre-commit hook.
This script performs safe checks on the codebase without accessing system prompts.
"""

import os
import subprocess
import sys
from pathlib import Path


def check_python_syntax():
    """Check Python files for syntax errors."""
    print("Checking Python syntax...")
    python_files = []
    for root, dirs, files in os.walk('.'):
        if '.git' in dirs:
            dirs.remove('.git')
        if '__pycache__' in dirs:
            dirs.remove('__pycache__')
        for file in files:
            if file.endswith('.py'):
                python_files.append(os.path.join(root, file))

    syntax_errors = []
    for py_file in python_files:
        try:
            with open(py_file, 'r', encoding='utf-8') as f:
                compile(f.read(), py_file, 'exec')
        except SyntaxError as e:
            syntax_errors.append(f"{py_file}:{e.lineno}: {e.msg}")

    if syntax_errors:
        print("Syntax errors found:")
        for error in syntax_errors:
            print(f"  {error}")
        return False
    print("✓ All Python files have valid syntax")
    return True


def check_import_consistency():
    """Check that imports are valid and consistent."""
    print("Checking import consistency...")
    try:
        result = subprocess.run([
            sys.executable, '-m', 'pyflakes'
        ], capture_output=True, text=True, cwd='.')

        if result.returncode != 0:
            print("Import issues found:")
            print(result.stdout)
            return False
        print("✓ All imports are valid")
        return True
    except FileNotFoundError:
        print("Warning: pyflakes not installed, skipping import checks")
        return True


def check_security_best_practices():
    """Basic security checks for common issues."""
    print("Checking security best practices...")
    security_issues = []

    for root, dirs, files in os.walk('.'):
        if '.git' in dirs:
            dirs.remove('.git')
        for file in files:
            if file.endswith('.py'):
                filepath = os.path.join(root, file)
                try:
                    with open(filepath, 'r', encoding='utf-8') as f:
                        content = f.read()
                        # Check for common security issues
                        if 'eval(' in content:
                            security_issues.append(f"{filepath}: Contains eval() usage")
                        if 'exec(' in content:
                            security_issues.append(f"{filepath}: Contains exec() usage")
                        if 'password' in content.lower() and '=' in content:
                            security_issues.append(f"{filepath}: May contain hardcoded password")
                except UnicodeDecodeError:
                    continue

    if security_issues:
        print("Potential security issues:")
        for issue in security_issues:
            print(f"  {issue}")
        return False
    print("✓ No obvious security issues found")
    return True


def main():
    """Main verification function."""
    print("Running codebase verification...")
    print("=" * 40)

    checks = [
        check_python_syntax,
        check_import_consistency,
        check_security_best_practices,
    ]

    all_passed = True
    for check in checks:
        if not check():
            all_passed = False
        print()

    if all_passed:
        print("✓ All checks passed!")
        return 0
    else:
        print("✗ Some checks failed!")
        return 1


if __name__ == "__main__":
    sys.exit(main())"
}

