  "file_path": "/root/populate_shm.c",
  "content": "#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/ipc.h>
#include <sys/shm.h>
#include <sys/mman.h>
#include <time.h>

int main() {
    int shmid[] = {0, 32769, 65538, 98307, 131076, 163845};
    size_t sizes[] = {1073741824, 1073741824, 1073741824, 1073741824, 2147483648, 2147483648};
    int num_segments = sizeof(shmid) / sizeof(shmid[0]);

    printf("Populating %d shared memory segments with random data...\n", num_segments);

    for (int i = 0; i < num_segments; i++) {
        printf("Processing segment %d (shmid: %d, size: %zu bytes)...\n", i, shmid[i], sizes[i]);

        // Attach to shared memory segment
        void *addr = shmat(shmid[i], NULL, 0);
        if (addr == (void *) -1) {
            perror("shmat");
            continue;
        }

        printf("  Attached at address %p\n", addr);

        // Use mlock to ensure pages stay in memory
        if (mlock(addr, sizes[i]) != 0) {
            perror("mlock");
            printf("  Warning: Could not lock pages in memory, continuing anyway...\n");
        }

        // Fill with random data in chunks to avoid large buffer allocation
        const size_t chunk_size = 1024 * 1024; // 1MB chunks
        char *chunk = malloc(chunk_size);
        if (!chunk) {
            printf("  Error: Could not allocate chunk buffer\n");
            shmdt(addr);
            continue;
        }

        // Initialize random seed
        srand(time(NULL) ^ (i << 16));

        size_t bytes_written = 0;
        char *current = (char *)addr;

        while (bytes_written < sizes[i]) {
            size_t write_size = (sizes[i] - bytes_written < chunk_size) ?
                               (sizes[i] - bytes_written) : chunk_size;

            // Fill chunk with random data
            for (size_t j = 0; j < write_size; j++) {
                chunk[j] = rand() & 0xFF;
            }

            // Copy to shared memory
            memcpy(current, chunk, write_size);
            current += write_size;
            bytes_written += write_size;

            // Progress indicator for large segments
            if (bytes_written % (100 * 1024 * 1024) == 0) {
                printf("  Written %zu MB...\n", bytes_written / (1024 * 1024));
            }
        }

        free(chunk);
        printf("  Completed writing %zu bytes (%.2f GB)\n", sizes[i], (double)sizes[i] / (1024*1024*1024));

        // Detach from shared memory
        if (shmdt(addr) != 0) {
            perror("shmdt");
        }
    }

    printf("\nAll segments populated with random data!\n");
    return 0;
}"
}

