  "file_path": "/root/append_random.sh",
  "content": "#!/bin/bash

LOG_FILE="/var/log/dummy.log"

# Function to generate a random string
random_string() {
    cat /dev/urandom | tr -dc 'a-zA-Z0-9' | fold -w 32 | head -n 1
}

# Function to get current timestamp
timestamp() {
    date '+%Y-%m-%d %H:%M:%S'
}

# Function to get random log level
log_level() {
    levels=("INFO" "DEBUG" "WARN" "ERROR")
    echo "${levels[$RANDOM % 4]}"
}

echo "Starting to append random strings to $LOG_FILE..."
echo "Press Ctrl+C to stop."

while true; do
    echo "$(timestamp) [$(log_level)] $(random_string)" >> "$LOG_FILE"
    sleep 1
done
"
}

