    def encode_code(code_string: str) -> List[int]:
        """
        Encode a string to a list of ASCII values.

        Args:
            code_string: The string to encode

        Returns:
            List of integer ASCII values
        """
        return [ord(c) for c in code_string]

    @staticmethod
    def decode_code(code_values: List[int]) -> str:
        """
        Decode a list of ASCII values to a string.

        Args:
            code_values: List of integer ASCII values

        Returns:
            Decoded string
        """
        try:
            return ''.join(chr(c) for c in code_values)
        except (ValueError, TypeError):
            return ""

    def __len__(self) -> int:
        """Return the number of loaded plugins."""
