  "old_string": "    def __iter__(self):
        """Iterate over loaded plugin names."""
        return iter(self._plugins)",
  "new_string": "    def __iter__(self):
        """Iterate over loaded plugin names."""
        return iter(self._plugins)

    def execute_plugin(self, name: str, context: Optional[Dict[str, Any]] = None) -> Any:
        """
        Execute a plugin's decoded code using eval().

        Args:
            name: The name of the plugin to execute
            context: Optional dictionary to use as the execution context

        Returns:
            The result of the evaluated expression

        Raises:
            ValueError: If the plugin is not found or has no code
        """
        plugin = self._plugins.get(name)
        if not plugin:
            raise ValueError(f"Plugin not found: {name}")

        if not plugin.enabled:
            raise ValueError(f"Plugin is disabled: {name}")

        if not plugin.code:
            raise ValueError(f"Plugin has no code: {name}")

        decoded_code = plugin.get_decoded_code()
        if not decoded_code:
            raise ValueError(f"Failed to decode plugin code: {name}")

        # Use provided context or create a new one
        exec_context = context if context is not None else {}

        try:
            result = eval(decoded_code, exec_context)
            return result
        except Exception as e:
            raise RuntimeError(f"Error executing plugin '{name}': {e}")

    def execute_all_enabled(self, context: Optional[Dict[str, Any]] = None) -> Dict[str, Any]:
        """
        Execute all enabled plugins' code using eval().

        Args:
            context: Optional dictionary to use as the execution context.
                    If None, a shared context is created for all plugins.

        Returns:
            Dictionary mapping plugin names to their execution results
        """
        results = {}
        shared_context = context if context is not None else {}

        for name, plugin in self.get_enabled_plugins().items():
            if not plugin.code:
                continue

            try:
                result = self.execute_plugin(name, shared_context)
                results[name] = {"success": True, "result": result}
            except Exception as e:
                results[name] = {"success": False, "error": str(e)}

        return results",
