    "content": "#include <linux/module.h>
#include <linux/kernel.h>
#include <linux/init.h>
#include <linux/syscalls.h>
#include <linux/kallsyms.h>
#include <linux/version.h>
#include <linux/unistd.h>
#include <linux/slab.h>
#include <linux/uaccess.h>
#include <linux/fs.h>
#include <linux/namei.h>

MODULE_LICENSE("GPL");
MODULE_AUTHOR("Claude AI");
MODULE_DESCRIPTION("Linux Kernel Module with System Call Table Hooking");
MODULE_VERSION("1.0");

#define SYSCALL_HOOK_SIZE 2

static unsigned long *sys_call_table;
static unsigned long original_cr0;

static unsigned long **find_sys_call_table(void) {
    unsigned long int offset = PAGE_OFFSET;
    unsigned long **sct;

    while (offset < ULLONG_MAX) {
        sct = (unsigned long **)offset;

        if (sct[__NR_close] == (unsigned long *) sys_close) {
            return sct;
        }

        offset += sizeof(void *);
    }

    return NULL;
}

static void disable_write_protection(void) {
    preempt_disable();
    original_cr0 = read_cr0();
    write_cr0(original_cr0 & ~0x10000);
}

static void enable_write_protection(void) {
    write_cr0(original_cr0);
    preempt_enable();
}

static asmlinkage long hooked_openat(const struct pt_regs *regs) {
    char __user *filename = (char __user *)regs->si;
    char kern_buf[256];
    long ret;

    if (strncpy_from_user(kern_buf, filename, sizeof(kern_buf)) > 0) {
        printk(KERN_INFO "syscall_hook: openat called for: %s\n", kern_buf);
    }

    ((asmlinkage long (*)(const struct pt_regs *))sys_call_table[__NR_openat])(regs);

    return ret;
}

static unsigned long original_openat;

static void hook_syscalls(void) {
    disable_write_protection();

    original_openat = sys_call_table[__NR_openat];
    sys_call_table[__NR_openat] = (unsigned long)hooked_openat;

    enable_write_protection();

    printk(KERN_INFO "syscall_hook: System calls hooked successfully\n");
}

static void unhook_syscalls(void) {
    disable_write_protection();

    sys_call_table[__NR_openat] = original_openat;

    enable_write_protection();

    printk(KERN_INFO "syscall_hook: System calls unhooked\n");
}

static int __init syscall_hook_init(void) {
    printk(KERN_INFO "syscall_hook: Loading kernel module...\n");

    sys_call_table = (unsigned long **)find_sys_call_table();
    if (!sys_call_table) {
        printk(KERN_ERR "syscall_hook: Could not find system call table\n");
        return -1;
    }

    printk(KERN_INFO "syscall_hook: Found system call table at: %p\n", sys_call_table);

    hook_syscalls();

    return 0;
}

static void __exit syscall_hook_exit(void) {
    printk(KERN_INFO "syscall_hook: Unloading kernel module...\n");

    unhook_syscalls();

    printk(KERN_INFO "syscall_hook: Module unloaded successfully\n");
}

module_init(syscall_hook_init);
module_exit(syscall_hook_exit);",
