    printk(KERN_INFO "EXECVE_MONITOR: Allocated major number %d\n", major_number);

    cdev_init(&execve_cdev, &fops);
    execve_cdev.owner = THIS_MODULE;

    ret = cdev_add(&execve_cdev, dev_num, 1);
    if (ret < 0) {
        printk(KERN_ERR "EXECVE_MONITOR: Failed to add cdev\n");
        goto error_cdev;
    }

    execve_class = class_create(THIS_MODULE, CLASS_NAME);
    if (IS_ERR(execve_class)) {
        printk(KERN_ERR "EXECVE_MONITOR: Failed to create device class\n");
        ret = PTR_ERR(execve_class);
        goto error_class;
