    execve_device = device_create(execve_class, NULL, dev_num, NULL, DEVICE_NAME);
    if (IS_ERR(execve_device)) {
        printk(KERN_ERR "EXECVE_MONITOR: Failed to create device\n");
        ret = PTR_ERR(execve_device);
        goto error_device;
