    printf("  -f, --follow   Monitor in real-time (default)\n");
    printf("  -c, --count    Exit after N events (0 = infinite)\n");
    printf("  -s, --stats    Show statistics every 100 events\n");
    printf("  -t, --timestamp Show human-readable timestamps\n");
    printf("\nExamples:\n");
    printf("  %s                    # Monitor in real-time\n", program);
    printf("  %s -c 50             # Show first 50 events then exit\n", program);
    printf("  %s -t                # Show human-readable timestamps\n", program);
}

void parse_execve_line(const char *line, int show_timestamp) {
    char timestamp_str[32], pid_str[16], uid_str[16];
    char command[BUFFER_SIZE];
    long timestamp_ms;
