    time_t timestamp_sec;
    struct tm *tm_info;
    char time_buf[64];

    if (strncmp(line, "EXECVE:", 7) != 0) {
        printf("%s", line);
        return;
    }

    if (sscanf(line, "EXECVE:%31[^:]:%15[^:]:%15[^:]:%[^\n]",
               timestamp_str, pid_str, uid_str, command) == 4) {
        timestamp_ms = atol(timestamp_str);
        pid = atoi(pid_str);
        uid = atoi(uid_str);

        if (show_timestamp) {
            timestamp_sec = timestamp_ms / 1000;
            tm_info = localtime(&timestamp_sec);
            strftime(time_buf, sizeof(time_buf), "%Y-%m-%d %H:%M:%S", tm_info);
            printf("[%s.%03ld] ", time_buf, timestamp_ms % 1000);
        } else {
            printf("[%ld] ", timestamp_ms);
        }

        printf("PID:%d UID:%d CMD:%s\n", pid, uid, command);
    } else {
        printf("Malformed line: %s\n", line);
    }
}

